<?php if($recurringCapabilities&&!in_array($recurrence['state'],['cancelled','completed'],true)){ ?><?= form_open($url());$hidden('recurring_control'); ?><input type="hidden" name="expense_id" value="<?= (int)$detail['id']; ?>"><input type="hidden" name="schedule_id" value="<?= (int)$recurrence['id']; ?>"><input type="hidden" name="schedule_revision" value="<?= (int)$recurrence['revision']; ?>"><?php if(in_array($recurrence['state'],['paused','paused_processing'],true)){ ?><button name="decision" value="resume" type="submit">Retomar agenda após revisão</button><?php }else{ ?><button name="decision" value="pause" type="submit">Pausar agenda</button><?php } ?><button name="decision" value="cancel" type="submit">Cancelar futuras etapas; preservar histórico</button><?= form_close(); ?>
