<p>Fila confirmada não comprova entrega SMTP.</p><table class="table"><thead><tr><th>Data prevista</th><th>Etapa</th><th>Despesa</th><th>Fatura</th><th>Notificação</th></tr></thead><tbody><?php foreach($recurrence['occurrences'] as $run){ ?><tr><td><?= $esc($run['run_date']); ?></td><td><?= $esc($recurrenceLabel($run['state'])); ?></td><td><?php if($run['expense_id']!==null){ ?><a href="<?= $esc($url('?expense='.(int)$run['expense_id'])); ?>">Abrir despesa <?= (int)$run['expense_id']; ?></a><?php } ?></td><td><?php if($run['invoice_id']!==null){ ?><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_invoices?invoice='.(int)$run['invoice_id'])); ?>">Abrir fatura <?= (int)$run['invoice_id']; ?></a><?php if(!$run['invoice_link_confirmed']){ ?> · Registrada; confirmação da etapa pendente<?php } ?><?php } ?></td><td><?= $run['queue_id']!==null?'Fila confirmada; entrega SMTP não confirmada':'Sem fila confirmada'; ?></td></tr><?php } ?></tbody></table></section><?php } ?>
